#include <zephyr/kernel.h>
#include <zephyr/kernel_structs.h>
#include <zephyr/sys/mem_blocks.h>
#include <zephyr/sys/util.h>
#include <string.h>
#include <stddef.h> /* For SIZE_MAX */

/*
 * @brief Initialize a heap
 *
 * @details This routine initializes a heap, prior to its first use.
 *
 * @param h Heap from which to allocate.
 * @param pBuf Pointer to the memory region to be used as a heap.
 * @param size The size of the memory region.
 */
void k_heap_init(struct k_heap *h, void *pBuf, size_t size)
{
    sys_mem_blocks_init(&h->mem_blocks, pBuf, size);
}

/*
 * @brief Allocate memory from a heap
 *
 * @details This routine allocates a block of memory from a heap.
 *
 * @param h Heap from which to allocate.
 * @param size The amount of memory to allocate (in bytes).
 * @param timeout Waiting period if heap is exhausted.
 *
 * @return A pointer to the allocated memory, or NULL if allocation fails.
 */
void *k_heap_alloc(struct k_heap *h, size_t size, k_timeout_t timeout)
{
    void *block;

    k_spinlock_key_t key = k_spin_lock(&h->lock);

    block = sys_mem_blocks_alloc(&h->mem_blocks, size);
    if (block == NULL) {
        if (K_TIMEOUT_EQ(timeout, K_NO_WAIT)) {
            k_spin_unlock(&h->lock, key);
            return NULL;
        }

        /* Wait for memory to become available */
        k_current_get()->base.swap_data = NULL;
        k_cond_wait(&h->wait_q, &h->lock, key, timeout);
        key = k_spin_lock(&h->lock); /* Re-acquire lock after wait */

        block = k_current_get()->base.swap_data;
    }

    k_spin_unlock(&h->lock, key);

    return block;
}

/*
 * @brief Allocate memory from a heap and zero it
 *
 * @details This routine allocates a block of memory from a heap and
 *          initializes all bytes in the block to zero.
 *
 * @param h Heap from which to allocate.
 * @param num_elements The number of elements to allocate.
 * @param element_size The size of each element (in bytes).
 *
 * @return A pointer to the allocated memory, or NULL if allocation fails.
 */
void *k_heap_calloc(struct k_heap *h, size_t num_elements, size_t element_size)
{
    size_t total_size;
    void *block;

    /* Check for zero size requests, which typically return NULL */
    if (num_elements == 0 || element_size == 0) {
        return NULL;
    }

    /* Check for potential overflow before calculating total_size */
    /* If num_elements * element_size would exceed SIZE_MAX, it's an overflow. */
    /* This check prevents total_size from wrapping around to a smaller value. */
    if (element_size > SIZE_MAX / num_elements) {
        return NULL; /* Overflow detected */
    }

    total_size = num_elements * element_size;

    block = k_heap_alloc(h, total_size, K_NO_WAIT); /* Use K_NO_WAIT for calloc by default */

    if (block != NULL) {
        memset(block, 0, total_size);
    }

    return block;
}

/*
 * @brief Free memory allocated from a heap
 *
 * @details This routine frees a block of memory that was allocated from a heap.
 *
 * @param h Heap from which memory was allocated.
 * @param block Pointer to the memory block to be freed.
 */
void k_heap_free(struct k_heap *h, void *block)
{
    k_spinlock_key_t key = k_spin_lock(&h->lock);

    sys_mem_blocks_free(&h->mem_blocks, block);

    /* Wake up any threads waiting for memory */
    k_cond_signal(&h->wait_q);

    k_spin_unlock(&h->lock, key);
}
